//! The C ABI. This is the **only** module allowed to contain `unsafe`, and it is
//! the only source of `include/pigeon_core.h` (generated by cbindgen).
//!
//! Rules that hold for every function here:
//!   * never panic across the boundary — every body goes through [`ffi_call`];
//!   * never block, never do IO;
//!   * report failure as NULL/0/false plus the thread-local error;
//!   * a successful call clears that error.
#![allow(non_camel_case_types)]
#![allow(clippy::not_unsafe_ptr_arg_deref)] // raw pointers are the contract; null is checked

use std::cell::{Cell, RefCell};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::ptr;

use crate::error::{PgError, PgResult};
use crate::layout::{Axis, Layout};
use crate::session::PaneState;
use crate::status::{Kind as StatusKind, State as StatusState};

pub mod msg;

pub use msg::*;

/// ABI generation. Bumped only for non-additive changes.
pub const PG_CORE_ABI_VERSION: u32 = 1;

// ---------------------------------------------------------------- errors

/// Result of the last call on this thread.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PgErrorCode {
    PG_OK = 0,
    /// Caller passed a bad size/version/enum value.
    PG_ERR_INVALID_ARG = 1,
    /// `pane_id` does not exist.
    PG_ERR_NO_SUCH_PANE = 2,
    /// `split_id` does not exist.
    PG_ERR_NO_SUCH_SPLIT = 3,
    /// Allocation failed.
    PG_ERR_NO_MEMORY = 4,
    /// Output buffer too small; retry with the reported size.
    PG_ERR_OVERFLOW = 5,
    /// A panic was caught at the FFI boundary.
    PG_ERR_PANIC = 6,
    /// Valid request, not implemented in this build.
    PG_ERR_UNSUPPORTED = 7,
}

impl From<PgError> for PgErrorCode {
    fn from(err: PgError) -> Self {
        match err {
            PgError::InvalidArg => Self::PG_ERR_INVALID_ARG,
            PgError::NoSuchPane => Self::PG_ERR_NO_SUCH_PANE,
            PgError::NoSuchSplit => Self::PG_ERR_NO_SUCH_SPLIT,
            PgError::NoMemory => Self::PG_ERR_NO_MEMORY,
            PgError::Overflow => Self::PG_ERR_OVERFLOW,
            PgError::Panic => Self::PG_ERR_PANIC,
            PgError::Unsupported => Self::PG_ERR_UNSUPPORTED,
        }
    }
}

/// UTF-8 bytes with an explicit length, never NUL-terminated.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgStr {
    /// `sizeof(PgStr)`.
    pub size: u32,
    /// Valid until the next core call on this thread.
    pub ptr: *const u8,
    pub len: usize,
}

thread_local! {
    static LAST_ERROR: RefCell<String> = const { RefCell::new(String::new()) };
    static LAST_ERROR_CODE: Cell<PgErrorCode> = const { Cell::new(PgErrorCode::PG_OK) };
}

fn clear_error() {
    LAST_ERROR_CODE.with(|c| c.set(PgErrorCode::PG_OK));
    LAST_ERROR.with(|s| s.borrow_mut().clear());
}

fn set_error(err: PgError) {
    LAST_ERROR_CODE.with(|c| c.set(err.into()));
    LAST_ERROR.with(|s| {
        let mut slot = s.borrow_mut();
        slot.clear();
        slot.push_str(&err.to_string());
    });
}

/// Runs one FFI body, converting panics and errors into the thread-local error.
fn ffi_call<T>(fallback: T, body: impl FnOnce() -> PgResult<T>) -> T {
    match catch_unwind(AssertUnwindSafe(body)) {
        Ok(Ok(value)) => {
            clear_error();
            value
        }
        Ok(Err(err)) => {
            set_error(err);
            fallback
        }
        Err(_) => {
            set_error(PgError::Panic);
            fallback
        }
    }
}

/// Thread-local; empty and `PG_OK` before the first failure.
#[no_mangle]
pub extern "C" fn pg_last_error() -> PgStr {
    LAST_ERROR.with(|s| {
        let mut slot = s.borrow_mut();
        slot.shrink_to_fit();
        PgStr {
            size: std::mem::size_of::<PgStr>() as u32,
            ptr: slot.as_ptr(),
            len: slot.len(),
        }
    })
}

/// Code of the last call on this thread; `PG_OK` after a successful one.
#[no_mangle]
pub extern "C" fn pg_last_error_code() -> PgErrorCode {
    LAST_ERROR_CODE.with(Cell::get)
}

/// The ABI generation this library was built with.
#[no_mangle]
pub extern "C" fn pg_core_abi_version() -> u32 {
    PG_CORE_ABI_VERSION
}

// -------------------------------------------------------------- lifetime

/// Opaque session container (one core owns N panes).
///
/// Declared in the generated header as `typedef struct PgCore PgCore;`.
pub struct PgCore {
    config: PgConfig,
    panes: std::collections::BTreeMap<u32, PaneState>,
    /// Geometry and focus live in the layout tree; the map only holds panes.
    layout: Option<Layout>,
    next_pane: u32,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgConfig {
    pub size: u32,
    pub version: u32,
    /// 0 = core default (10000 lines); capped at 100000.
    pub scrollback_lines: u32,
    pub osc7501_enabled: u8,
}

impl PgConfig {
    const DEFAULT: Self = Self {
        size: std::mem::size_of::<Self>() as u32,
        version: PG_CORE_ABI_VERSION,
        scrollback_lines: 0,
        osc7501_enabled: 1,
    };
}

/// Returns NULL on failure. `cfg == NULL` means defaults.
#[no_mangle]
pub extern "C" fn pg_core_new(cfg: *const PgConfig) -> *mut PgCore {
    ffi_call(ptr::null_mut(), || {
        let config = if cfg.is_null() {
            PgConfig::DEFAULT
        } else {
            // SAFETY: the caller guarantees a readable PgConfig for the ABI.
            let config = unsafe { *cfg };
            if usize::try_from(config.size).unwrap_or(0) < std::mem::size_of::<PgConfig>() {
                return Err(PgError::InvalidArg);
            }
            if config.version > PG_CORE_ABI_VERSION {
                return Err(PgError::InvalidArg);
            }
            config
        };
        Ok(Box::into_raw(Box::new(PgCore {
            config,
            panes: std::collections::BTreeMap::new(),
            layout: None,
            next_pane: 1,
        })))
    })
}

/// Frees a core created by [`pg_core_new`]; NULL is a no-op.
#[no_mangle]
pub extern "C" fn pg_core_free(core: *mut PgCore) {
    ffi_call((), || {
        if !core.is_null() {
            // SAFETY: pointer came from pg_core_new and is freed exactly once.
            drop(unsafe { Box::from_raw(core) });
        }
        Ok(())
    });
}

// ----------------------------------------------------------------- panes

#[repr(C)]
pub struct PgPaneOptions {
    pub size: u32,
    pub version: u32,
    pub cols: u16,
    pub rows: u16,
    /// Optional: `ptr` may be NULL.
    pub title: PgStr,
}

/// Creates a pane. Returns 0 on failure (ids start at 1). `opts == NULL` means
/// 80x24 with the core's scrollback setting.
#[no_mangle]
pub extern "C" fn pg_pane_new(core: *mut PgCore, opts: *const PgPaneOptions) -> u32 {
    ffi_call(0, || {
        let core = unsafe_mut(core)?;
        let (cols, rows) = read_pane_options(opts)?.unwrap_or((80, 24));
        let pane_id = core.next_pane;
        core.next_pane = core.next_pane.saturating_add(1);
        if core.layout.is_some() {
            // Extra panes come from `pg_layout_split`, which knows the geometry.
            return Err(PgError::InvalidArg);
        }
        let history = scrollback_lines(&core.config);
        core.panes
            .insert(pane_id, PaneState::new(pane_id, cols, rows, history));
        core.layout = Some(Layout::new(pane_id));
        Ok(pane_id)
    })
}

#[no_mangle]
pub extern "C" fn pg_pane_free(core: *mut PgCore, pane_id: u32) {
    ffi_call((), || {
        let core = unsafe_mut(core)?;
        core.panes.remove(&pane_id).ok_or(PgError::NoSuchPane)?;
        if let Some(layout) = core.layout.as_mut() {
            let _ = layout.close(pane_id);
        }
        Ok(())
    });
}

/// Parses bytes; never blocks, never echoes.
#[no_mangle]
pub extern "C" fn pg_pane_feed(
    core: *mut PgCore,
    pane_id: u32,
    data: *const u8,
    len: usize,
) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        // SAFETY: caller promises `len` readable bytes at `data`.
        let bytes = unsafe { byte_slice(data, len) }?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        pane.feed(bytes);
        Ok(true)
    })
}

#[no_mangle]
pub extern "C" fn pg_pane_resize(core: *mut PgCore, pane_id: u32, cols: u16, rows: u16) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        pane.resize(cols, rows);
        Ok(true)
    })
}

/// Pulls pending terminal replies (DA/DSR/…); returns bytes written.
#[no_mangle]
pub extern "C" fn pg_pane_respond(
    core: *mut PgCore,
    pane_id: u32,
    out: *mut u8,
    cap: usize,
) -> usize {
    ffi_call(0, || {
        let core = unsafe_mut(core)?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        let replies = pane.take_replies();
        if replies.is_empty() {
            return Ok(0);
        }
        if out.is_null() || cap < replies.len() {
            return Err(PgError::Overflow);
        }
        // SAFETY: caller provided `cap` writable bytes.
        unsafe { ptr::copy_nonoverlapping(replies.as_ptr(), out, replies.len()) };
        Ok(replies.len())
    })
}

// -------------------------------------------------------------- snapshot

/// Attribute bits carried by [`PgCell::attrs`].
pub const PG_ATTR_BOLD: u32 = 1 << 0;
pub const PG_ATTR_ITALIC: u32 = 1 << 1;
pub const PG_ATTR_UNDERLINE: u32 = 1 << 2;
pub const PG_ATTR_REVERSE: u32 = 1 << 3;
pub const PG_ATTR_STRIKETHROUGH: u32 = 1 << 4;
pub const PG_ATTR_DIM: u32 = 1 << 5;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgCell {
    pub size: u32,
    pub codepoint: u32,
    /// `0x01000000 | idx` for a palette entry, else `0xRRGGBB`.
    pub fg: u32,
    pub bg: u32,
    /// `PG_ATTR_*` bitmask.
    pub attrs: u32,
    /// 0 = no link.
    pub hyperlink_id: u32,
    /// 1 or 2; a wide char owns the next cell.
    pub width: u8,
}

#[repr(C)]
pub struct PgRow {
    pub size: u32,
    /// Exactly `cols` entries.
    pub cells: *const PgCell,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgCursor {
    pub size: u32,
    pub x: u16,
    pub y: u16,
    pub visible: u8,
    /// 0 block, 1 underline, 2 bar.
    pub shape: u8,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgScrollRegion {
    pub size: u32,
    pub top: u16,
    pub bottom: u16,
}

#[repr(C)]
pub struct PgSnapshot {
    pub size: u32,
    pub version: u32,
    pub pane_id: u32,
    pub cols: u16,
    pub rows: u16,
    pub alt_screen: u8,
    pub cursor: PgCursor,
    pub scroll_region: PgScrollRegion,
    /// `rows` entries: the visible grid.
    pub screen: *const PgRow,
    /// `history_count` entries, oldest first; may be NULL.
    pub history: *const PgRow,
    pub history_count: u32,
}

/// Owned by the caller; free with [`pg_snapshot_free`]. Immutable, thread-safe.
#[no_mangle]
pub extern "C" fn pg_pane_snapshot(core: *mut PgCore, pane_id: u32) -> *mut PgSnapshot {
    ffi_call(ptr::null_mut(), || {
        let core = unsafe_mut(core)?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        let snapshot = pane.snapshot();
        snapshot_to_ffi(pane_id, &snapshot, true)
    })
}

/// Fills row indices dirty since the last call; returns how many were written.
#[no_mangle]
pub extern "C" fn pg_pane_dirty_rows(
    core: *mut PgCore,
    pane_id: u32,
    out: *mut u16,
    cap: usize,
) -> usize {
    ffi_call(0, || {
        let core = unsafe_mut(core)?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        let dirty = pane.take_damage();
        if out.is_null() && !dirty.is_empty() {
            return Err(PgError::InvalidArg);
        }
        let written = dirty.len().min(cap);
        if written > 0 {
            // SAFETY: caller provided `cap` writable entries.
            unsafe { ptr::copy_nonoverlapping(dirty.as_ptr(), out, written) };
        }
        Ok(written)
    })
}

#[no_mangle]
pub extern "C" fn pg_snapshot_free(snap: *mut PgSnapshot) {
    ffi_call((), || {
        if snap.is_null() {
            return Ok(());
        }
        // SAFETY: pointer came from build_snapshot and is freed exactly once.
        let snap = unsafe { Box::from_raw(snap) };
        let cols = usize::from(snap.cols);
        let rows = usize::from(snap.rows);
        unsafe {
            if rows > 0 && !snap.screen.is_null() {
                reclaim((*snap.screen).cells.cast_mut(), rows * cols);
            }
            reclaim(snap.screen.cast_mut(), rows);
            let history_rows = snap.history_count as usize;
            if history_rows > 0 && !snap.history.is_null() {
                reclaim((*snap.history).cells.cast_mut(), history_rows * cols);
            }
            reclaim(snap.history.cast_mut(), history_rows);
        }
        Ok(())
    });
}

/// Takes ownership of `screen`/`history` cell grids and returns a snapshot the
/// caller frees with [`pg_snapshot_free`].
#[allow(clippy::too_many_arguments)] // mirrors PgSnapshot's own fields
pub(crate) fn build_snapshot(
    pane_id: u32,
    cols: u16,
    rows: u16,
    alt: bool,
    cursor: PgCursor,
    scroll: PgScrollRegion,
    screen: Vec<Vec<PgCell>>,
    history: Vec<Vec<PgCell>>,
) -> PgResult<*mut PgSnapshot> {
    // pg_snapshot_free reclaims `rows * cols` screen cells and
    // `history_count * cols` history cells, and every PgRow below points
    // `index * cols` cells into the flat grid, so the grids must be exactly
    // that shape. Anything else (a malformed wire snapshot, say) is refused
    // here rather than handed to C as an out-of-bounds pointer.
    let col_count = usize::from(cols);
    let well_formed = |grid: &[Vec<PgCell>]| grid.iter().all(|row| row.len() == col_count);
    if screen.len() != usize::from(rows) || !well_formed(&screen) || !well_formed(&history) {
        return Err(PgError::InvalidArg);
    }
    let history_count = u32::try_from(history.len()).map_err(|_| PgError::InvalidArg)?;
    let mut screen_cells = screen
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .into_boxed_slice();
    let mut history_cells = history
        .into_iter()
        .flatten()
        .collect::<Vec<_>>()
        .into_boxed_slice();

    let row_count = usize::from(rows);

    let screen_ptr = screen_cells.as_mut_ptr();
    let history_ptr = history_cells.as_mut_ptr();

    let screen_rows = (0..row_count)
        .map(|index| PgRow {
            size: std::mem::size_of::<PgRow>() as u32,
            // SAFETY: `screen_cells.len() == row_count * col_count`, checked above.
            cells: unsafe { screen_ptr.add(index * col_count) }.cast_const(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();

    let history_rows = (0..history_count as usize)
        .map(|index| PgRow {
            size: std::mem::size_of::<PgRow>() as u32,
            // SAFETY: `history_cells.len() == history_count * col_count`, checked above.
            cells: unsafe { history_ptr.add(index * col_count) }.cast_const(),
        })
        .collect::<Vec<_>>()
        .into_boxed_slice();

    let snapshot = PgSnapshot {
        size: std::mem::size_of::<PgSnapshot>() as u32,
        version: PG_CORE_ABI_VERSION,
        pane_id,
        cols,
        rows,
        alt_screen: u8::from(alt),
        cursor,
        scroll_region: scroll,
        screen: screen_rows.as_ptr(),
        history: history_rows.as_ptr(),
        history_count,
    };

    // The rows borrow the cell grids, so all three allocations leak together and
    // are reclaimed together in pg_snapshot_free.
    std::mem::forget(screen_rows);
    std::mem::forget(history_rows);
    std::mem::forget(screen_cells);
    std::mem::forget(history_cells);

    Ok(Box::into_raw(Box::new(snapshot)))
}

/// # Safety
/// `ptr` must come from a `Box<[T]>` that was leaked with the same `len`.
unsafe fn reclaim<T>(ptr: *mut T, len: usize) {
    if len == 0 || ptr.is_null() {
        return;
    }
    // SAFETY: caller guarantees the allocation and length.
    drop(unsafe { Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, len)) });
}

// ---------------------------------------------------------------- status

#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PgStatusState {
    PG_STATE_IDLE = 0,
    PG_STATE_WORKING = 1,
    PG_STATE_BLOCKED = 2,
    PG_STATE_DONE = 3,
    PG_STATE_ERROR = 4,
}

#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PgStatusKind {
    PG_KIND_NONE = 0,
    PG_KIND_PERMISSION = 1,
    PG_KIND_QUESTION = 2,
    PG_KIND_AUTH = 3,
}

#[repr(C)]
pub struct PgStatus {
    pub size: u32,
    pub version: u32,
    pub pane_id: u32,
    /// Monotonic per pane.
    pub seq: u32,
    pub state: PgStatusState,
    pub kind: PgStatusKind,
    /// Plain text only; never interpreted as markup.
    pub msg: PgStr,
}

#[no_mangle]
pub extern "C" fn pg_status_count(core: *mut PgCore) -> usize {
    ffi_call(0, || {
        let core = unsafe_ref(core)?;
        Ok(focused(core)?.status().len())
    })
}

/// Fills `out` with the focused pane's status record at `index`.
#[no_mangle]
pub extern "C" fn pg_status_at(core: *mut PgCore, index: usize, out: *mut PgStatus) -> bool {
    ffi_call(false, || {
        let core = unsafe_ref(core)?;
        if out.is_null() {
            return Err(PgError::InvalidArg);
        }
        let pane = focused(core)?;
        let record = pane
            .status()
            .records()
            .nth(index)
            .ok_or(PgError::InvalidArg)?;
        // SAFETY: `out` checked above; `msg` borrows the record, which stays
        // alive until the next mutation of this core (documented in the header).
        unsafe {
            *out = PgStatus {
                size: std::mem::size_of::<PgStatus>() as u32,
                version: PG_CORE_ABI_VERSION,
                pane_id: pane.pane_id,
                seq: record.seq,
                state: map_state(record.state),
                kind: map_kind(record.kind),
                msg: PgStr {
                    size: std::mem::size_of::<PgStr>() as u32,
                    ptr: record.msg.as_ptr(),
                    len: record.msg.len(),
                },
            }
        };
        Ok(true)
    })
}

/// Marks a done/error record as seen; it may then be evicted.
#[no_mangle]
pub extern "C" fn pg_status_ack(core: *mut PgCore, pane_id: u32, seq: u32) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        let pane = core.panes.get_mut(&pane_id).ok_or(PgError::NoSuchPane)?;
        Ok(pane.status_mut().ack("", seq))
    })
}

// ---------------------------------------------------------------- layout

#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PgAxis {
    /// Panes side by side, vertical divider ("v" in the protocol).
    PG_AXIS_VERTICAL = 0,
    /// Panes stacked, horizontal divider ("h" in the protocol).
    PG_AXIS_HORIZONTAL = 1,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgRect {
    pub size: u32,
    pub pane_id: u32,
    /// Normalized 0..1, relative to the session box.
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
}

/// Splits a pane and returns the **new pane id** (0 on failure).
#[no_mangle]
pub extern "C" fn pg_layout_split(
    core: *mut PgCore,
    pane_id: u32,
    axis: PgAxis,
    ratio: f32,
) -> u32 {
    ffi_call(0, || {
        let core = unsafe_mut(core)?;
        let (cols, rows) = core
            .panes
            .get(&pane_id)
            .map(PaneState::size)
            .ok_or(PgError::NoSuchPane)?;
        let axis = match axis {
            PgAxis::PG_AXIS_VERTICAL => Axis::Vertical,
            PgAxis::PG_AXIS_HORIZONTAL => Axis::Horizontal,
        };
        // The target pane's own size is the extent being divided.
        let new_id = core.next_pane;
        core.next_pane = core.next_pane.saturating_add(1);
        let layout = core.layout.as_mut().ok_or(PgError::NoSuchPane)?;
        layout.split(pane_id, new_id, axis, ratio, cols, rows)?;
        let (child_cols, child_rows) = match axis {
            Axis::Vertical => ((cols / 2).max(2), rows),
            Axis::Horizontal => (cols, (rows / 2).max(1)),
        };
        let history = scrollback_lines(&core.config);
        let mut pane = PaneState::new(new_id, child_cols, child_rows, history);
        pane.resize(child_cols, child_rows);
        core.panes.insert(new_id, pane);
        let _ = layout.focus(new_id);
        Ok(new_id)
    })
}

/// Closes a pane; its sibling takes over the parent rect.
#[no_mangle]
pub extern "C" fn pg_layout_close(core: *mut PgCore, pane_id: u32) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        core.panes.remove(&pane_id).ok_or(PgError::NoSuchPane)?;
        if let Some(layout) = core.layout.as_mut() {
            layout.close(pane_id)?;
        }
        Ok(true)
    })
}

/// Changes a split's ratio; clamped so both sides keep their minimum size.
#[no_mangle]
pub extern "C" fn pg_layout_resize(core: *mut PgCore, split_id: u32, ratio: f32) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        let (cols, rows) = focused(core)?.size();
        let layout = core.layout.as_mut().ok_or(PgError::NoSuchSplit)?;
        layout.set_ratio(split_id, ratio, cols, rows)?;
        Ok(true)
    })
}

/// A divider in a layout message: the box it divides plus its ratio.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct PgSplit {
    pub size: u32,
    pub id: u32,
    pub axis: PgAxis,
    pub ratio: f32,
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
}

/// One normalized rect per pane, in tree order.
#[no_mangle]
pub extern "C" fn pg_layout_rects(core: *mut PgCore, out: *mut PgRect, cap: usize) -> usize {
    ffi_call(0, || {
        let core = unsafe_ref(core)?;
        let layout = core.layout.as_ref().ok_or(PgError::NoSuchPane)?;
        let rects = layout.rects();
        if rects.is_empty() {
            return Ok(0);
        }
        if out.is_null() || cap < rects.len() {
            return Err(PgError::Overflow);
        }
        for (index, (pane_id, rect)) in rects.iter().enumerate() {
            // SAFETY: `cap` entries were promised by the caller.
            unsafe {
                *out.add(index) = PgRect {
                    size: std::mem::size_of::<PgRect>() as u32,
                    pane_id: *pane_id,
                    x: rect.x,
                    y: rect.y,
                    w: rect.w,
                    h: rect.h,
                };
            }
        }
        Ok(rects.len())
    })
}

/// The split to resize when the user drags the divider next to `pane_id`;
/// 0 when the pane has no parent split.
#[no_mangle]
pub extern "C" fn pg_layout_split_of(core: *mut PgCore, pane_id: u32) -> u32 {
    ffi_call(0, || {
        let core = unsafe_ref(core)?;
        if !core.panes.contains_key(&pane_id) {
            return Err(PgError::NoSuchPane);
        }
        Ok(core
            .layout
            .as_ref()
            .and_then(|layout| layout.split_of(pane_id))
            .unwrap_or(0))
    })
}

#[no_mangle]
pub extern "C" fn pg_layout_focus(core: *mut PgCore, pane_id: u32) -> bool {
    ffi_call(false, || {
        let core = unsafe_mut(core)?;
        let layout = core.layout.as_mut().ok_or(PgError::NoSuchPane)?;
        if layout.focus(pane_id) {
            Ok(true)
        } else {
            Err(PgError::NoSuchPane)
        }
    })
}

#[no_mangle]
pub extern "C" fn pg_layout_focused(core: *mut PgCore) -> u32 {
    ffi_call(0, || {
        Ok(unsafe_ref(core)?
            .layout
            .as_ref()
            .and_then(Layout::focused)
            .unwrap_or(0))
    })
}

// ---------------------------------------------------------------- helpers

/// Borrows `len` bytes at `data` as a slice. `(NULL, 0)` is the empty slice:
/// `std::slice::from_raw_parts` requires a non-null pointer even for length 0,
/// and C/Swift callers routinely pass NULL for an empty buffer.
///
/// # Safety
/// When `len > 0`, `data` must point to `len` readable bytes that outlive `'a`.
pub(crate) unsafe fn byte_slice<'a>(data: *const u8, len: usize) -> PgResult<&'a [u8]> {
    if len == 0 {
        return Ok(&[]);
    }
    if data.is_null() {
        return Err(PgError::InvalidArg);
    }
    // SAFETY: non-null and `len` readable bytes, per the caller's contract.
    Ok(unsafe { std::slice::from_raw_parts(data, len) })
}

fn unsafe_ref<'a>(core: *const PgCore) -> PgResult<&'a PgCore> {
    if core.is_null() {
        return Err(PgError::InvalidArg);
    }
    // SAFETY: the caller guarantees a live handle.
    Ok(unsafe { &*core })
}

fn unsafe_mut<'a>(core: *mut PgCore) -> PgResult<&'a mut PgCore> {
    if core.is_null() {
        return Err(PgError::InvalidArg);
    }
    // SAFETY: the caller guarantees a live handle and serialized access.
    Ok(unsafe { &mut *core })
}

fn focused(core: &PgCore) -> PgResult<&PaneState> {
    let pane_id = core
        .layout
        .as_ref()
        .and_then(Layout::focused)
        .ok_or(PgError::NoSuchPane)?;
    core.panes.get(&pane_id).ok_or(PgError::NoSuchPane)
}

fn scrollback_lines(config: &PgConfig) -> usize {
    match config.scrollback_lines {
        0 => 10_000,
        lines => usize::try_from(lines.min(100_000)).unwrap_or(10_000),
    }
}

fn read_pane_options(opts: *const PgPaneOptions) -> PgResult<Option<(u16, u16)>> {
    if opts.is_null() {
        return Ok(None);
    }
    // SAFETY: caller guarantees a readable PgPaneOptions.
    let opts = unsafe { &*opts };
    if usize::try_from(opts.size).unwrap_or(0) < std::mem::size_of::<PgPaneOptions>() {
        return Err(PgError::InvalidArg);
    }
    Ok(Some((opts.cols.max(2), opts.rows.max(1))))
}

fn map_state(state: StatusState) -> PgStatusState {
    match state {
        StatusState::Idle => PgStatusState::PG_STATE_IDLE,
        StatusState::Working => PgStatusState::PG_STATE_WORKING,
        StatusState::Blocked => PgStatusState::PG_STATE_BLOCKED,
        StatusState::Done => PgStatusState::PG_STATE_DONE,
        StatusState::Error => PgStatusState::PG_STATE_ERROR,
    }
}

fn map_kind(kind: StatusKind) -> PgStatusKind {
    match kind {
        StatusKind::None => PgStatusKind::PG_KIND_NONE,
        StatusKind::Permission => PgStatusKind::PG_KIND_PERMISSION,
        StatusKind::Question => PgStatusKind::PG_KIND_QUESTION,
        StatusKind::Auth => PgStatusKind::PG_KIND_AUTH,
    }
}

/// Converts a terminal-domain snapshot into an owned C snapshot.
fn snapshot_to_ffi(
    pane_id: u32,
    snapshot: &crate::term::Snapshot,
    with_history: bool,
) -> PgResult<*mut PgSnapshot> {
    let screen = snapshot
        .screen
        .iter()
        .map(|row| row.iter().map(to_pg_cell).collect())
        .collect();
    let history = if with_history {
        snapshot
            .history
            .iter()
            .map(|row| row.iter().map(to_pg_cell).collect())
            .collect()
    } else {
        Vec::new()
    };
    build_snapshot(
        pane_id,
        snapshot.cols,
        snapshot.rows,
        snapshot.alt,
        PgCursor {
            size: std::mem::size_of::<PgCursor>() as u32,
            x: snapshot.cursor.x,
            y: snapshot.cursor.y,
            visible: u8::from(snapshot.cursor.visible),
            shape: snapshot.cursor.shape,
        },
        PgScrollRegion {
            size: std::mem::size_of::<PgScrollRegion>() as u32,
            top: snapshot.scroll.0,
            bottom: snapshot.scroll.1,
        },
        screen,
        history,
    )
}

fn to_pg_cell(cell: &crate::term::Cell) -> PgCell {
    PgCell {
        size: std::mem::size_of::<PgCell>() as u32,
        codepoint: cell.codepoint,
        fg: cell.fg,
        bg: cell.bg,
        attrs: cell.attrs,
        hyperlink_id: cell.link,
        width: cell.width,
    }
}
